func establishAssociation(conn *net.UDPConn, nodeID string) error {
	log.Println("[*] Phase 1: Establishing PFCP association...")

	req := message.NewAssociationSetupRequest(
		1,
		ie.NewNodeID("", "", nodeID),
		ie.NewRecoveryTimeStamp(time.Now()),
	)

	b := make([]byte, req.MarshalLen())
	if err := req.MarshalTo(b); err != nil {
		return fmt.Errorf("marshal failed: %v", err)
	}
	if _, err := conn.Write(b); err != nil {
		return fmt.Errorf("send failed: %v", err)
	}

	buf := make([]byte, 1500)
	_ = conn.SetReadDeadline(time.Now().Add(3 * time.Second))
	if n, err := conn.Read(buf); err == nil {
		log.Printf("[+] Association established (%d bytes)", n)
	} else {
		log.Printf("[!] Association response not received (continuing): %v", err)
	}
	_ = conn.SetReadDeadline(time.Time{})
	return nil
}

