// PrfPlus implements RFC 7296 PRF+ key expansion
func prfPlus(prfKey []byte, seed []byte, totalLen int) []byte {
	var stream, prevBlock []byte
	for i := 1; len(stream) < totalLen; i++ {
		mac := hmac.New(sha1.New, prfKey)
		mac.Write(prevBlock)
		mac.Write(seed)
		mac.Write([]byte{byte(i)})
		prevBlock = mac.Sum(nil)
		stream = append(stream, prevBlock...)
	}
	return stream[:totalLen]
}

